insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_pe_v1'
from (values
('116.15.b.1.A',3,'A leap is different from a jump because in a leap you take off from one foot and land on the...','["other foot", "same two feet", "hands", "knees"]'::jsonb,0,'A leap moves from one foot to the other in the air.','original'),
('116.15.b.1.A',3,'Which locomotor skill is a running step where you stretch your legs wide in the air?','["sitting", "leaping", "sliding", "crawling"]'::jsonb,1,'Leaps are long, airborne strides.','original'),
('116.15.b.1.A',3,'In a proper skip, you...','["jump on two feet", "only walk", "step and hop on one foot, then the other", "only crawl"]'::jsonb,2,'Skipping alternates step-hops.','original'),
('116.15.b.1.B',3,'When jumping down from a low platform, you should land with...','["your head first", "stiff legs", "your hands first", "soft, bent knees"]'::jsonb,3,'Absorb force by bending knees.','original'),
('116.15.b.1.B',3,'Landing from a higher height needs a more...','["controlled landing", "backward landing", "careless landing", "loud landing"]'::jsonb,0,'Greater height means more force.','original'),
('116.15.b.1.C',3,'Walking along a low balance beam is an example of...','["a race", "intermediate balancing with equipment", "a game of tag", "a rest"]'::jsonb,1,'Equipment adds challenge to balance.','original'),
('116.15.b.1.C',3,'Skipping with arms swinging in opposition uses...','["only one side of the body", "none of the body", "cross lateral coordination", "no coordination"]'::jsonb,2,'Opposite arm and leg move together.','original'),
('116.15.b.1.D',3,'Spinning with control while holding a scarf means you...','["let go", "fall down", "close your eyes", "keep your balance and watch the scarf"]'::jsonb,3,'Control means steady movement.','original'),
('116.15.b.2.A',3,'Moving in and out of a balanced position with control is useful when you...','["change directions in a game", "sit still", "sleep", "take a nap"]'::jsonb,0,'Dynamic balance helps in sports.','original'),
('116.15.b.2.B',3,'A movement that combines bending and stretching could be...','["sitting", "reaching for a high shelf then crouching", "sleeping", "standing still"]'::jsonb,1,'It uses two actions.','original'),
('116.15.b.3.A',3,'An accurate overhand throw means you...','["look away", "throw as hard as you can at anything", "aim at the target and follow through", "swing your arm backward"]'::jsonb,2,'Accuracy needs aim and follow-through.','original'),
('116.15.b.3.A',3,'Which throw uses a swinging arm from low to high?','["overhand", "sidearm only", "none", "underhand"]'::jsonb,3,'Underhand swings from low.','original'),
('116.15.b.3.B',3,'When catching a soft toss, you reach out and then...','["give with the ball by pulling your hands in", "snap your arms straight", "close your eyes", "turn away"]'::jsonb,0,'"Giving" absorbs the force.','original'),
('116.15.b.3.C',3,'Dribbling while slowly jogging means you...','["kick the ball", "keep the ball under control as you move", "throw the ball", "stop dribbling"]'::jsonb,1,'Control is key.','original'),
('116.15.b.3.D',3,'When dribbling a soccer ball while jogging, you should tap the ball...','["with your hands", "with all your force", "lightly so it stays near your feet", "backward"]'::jsonb,2,'Light touches keep control.','original'),
('116.15.b.3.E',3,'Kicking a rolling ball on the ground means you...','["stand far away", "close your eyes", "run in a circle", "time your kick with the ball''s movement"]'::jsonb,3,'Timing is essential.','original'),
('116.15.b.3.E',3,'To kick a ball into the air, you should contact the...','["bottom of the ball", "side of the ball only", "top of the ball", "nothing"]'::jsonb,0,'Kicking low lifts it.','original'),
('116.15.b.3.F',3,'When volleying a ball over a net, you should use your...','["ears", "hands or forearms", "elbows", "knees only"]'::jsonb,1,'Forearms make a flat platform.','original'),
('116.15.b.3.G',3,'To strike a moving ball with a paddle, you should...','["stand still", "throw the paddle", "watch the ball and swing at it", "close your eyes"]'::jsonb,2,'Eye-hand coordination is key.','original'),
('116.15.b.3.H',3,'Which is a basic jump rope skill?','["dancing without a rope", "cutting the rope", "climbing the rope", "jumping with both feet"]'::jsonb,3,'Two-foot jumps are the basic skill.','original'),
('116.15.b.3.I',3,'To enter a turned long rope, you should...','["run in when the rope reaches the ground", "stand still and wait forever", "step in while it is overhead", "grab the rope"]'::jsonb,0,'Enter just as the rope hits the ground.','original'),
('116.15.b.3.I',3,'To exit a long rope, a jumper should...','["hold the rope", "run out after a jump", "sit down", "stop in the middle"]'::jsonb,1,'Exit through the side.','original'),
('116.15.b.4.A',3,'Open space in a gym is...','["a small corner", "a locked room", "an area free of people and objects", "a closet"]'::jsonb,2,'Open space is where you can move freely.','original'),
('116.15.b.4.B',3,'Combining pathways and levels could look like...','["standing still", "sleeping", "clapping", "a zigzag path then a low roll"]'::jsonb,3,'They mix paths and heights.','original'),
('116.15.b.4.C',3,'Combining force with speed could mean...','["moving fast with a strong push", "sitting", "moving slowly with a tiny tap", "none"]'::jsonb,0,'Force and speed combine for different effects.','original'),
('116.15.b.5',3,'Folk dances often use...','["no music", "steps in a set pattern to music", "random movement", "no steps"]'::jsonb,1,'They follow patterns and rhythm.','original'),
('116.15.b.5',3,'A rhythm pattern in dance is usually repeated every...','["week", "day", "measure or phrase", "year"]'::jsonb,2,'Music is organized in phrases.','original'),
('116.15.b.6.A',3,'A game that combines chasing, fleeing, and dodging requires you to...','["stand still", "sit", "nap", "think quickly and change direction"]'::jsonb,3,'Games call for several skills together.','original'),
('116.15.b.6.B',3,'To improve a movement skill, you can...','["practice it correctly several times", "avoid it", "ignore it", "skip it"]'::jsonb,0,'Practice improves skills.','original'),
('116.15.b.6.C',3,'Following game rules makes the game...','["boring", "fair and safe", "longer", "dangerous"]'::jsonb,1,'Rules protect players.','original'),
('116.15.b.7',3,'A skill for an outdoor adventure like orienteering is...','["baking", "painting", "reading a map and compass", "dancing"]'::jsonb,2,'Orienteering uses navigation.','original'),
('116.15.b.7',3,'A good rule for camping safety is to...','["play with fire", "leave trash", "wander off", "stay with the group and tell an adult where you go"]'::jsonb,3,'Camping safety means planning.','original'),
('116.15.b.8.A',3,'One way regular exercise helps manage stress is by...','["releasing tension and improving your mood", "keeping you awake", "making you worry", "making you angry"]'::jsonb,0,'Activity helps your mood.','original'),
('116.15.b.8.B',3,'In endurance activities, intensity means...','["how long the class is", "how hard you work", "how loud you are", "how tall you are"]'::jsonb,1,'Intensity is effort level.','original'),
('116.15.b.8.B',3,'In endurance activities, frequency means...','["how hard you work", "how heavy you are", "how often you do the activity", "what you wear"]'::jsonb,2,'Frequency is how many times a week.','original'),
('116.15.b.8.C',3,'A correct sit-up (curl-up) is done by...','["jumping", "pulling your neck", "swinging your arms", "curling your upper body toward your knees"]'::jsonb,3,'Curl-ups work the abdominal muscles.','original'),
('116.15.b.8.C',3,'Flexibility is the ability to...','["move your joints through a full range of motion", "lift heavy things", "run fast", "hold your breath"]'::jsonb,0,'Stretching builds flexibility.','original'),
('116.15.b.9.A',3,'Setting personal fitness goals helps because they...','["have no purpose", "give you something to work toward", "are impossible", "make you quit"]'::jsonb,1,'Goals provide direction.','original'),
('116.15.b.9.B',3,'One way to track fitness progress is to...','["guess", "hide your scores", "record your scores in a chart", "forget your scores"]'::jsonb,2,'Charts show improvement.','original'),
('116.15.b.10.A',3,'Which food is a healthy source of energy?','["chips", "candy", "soda", "whole-grain bread"]'::jsonb,3,'Whole grains give steady energy.','original'),
('116.15.b.10.A',3,'A food high in sugar gives energy that...','["runs out quickly", "builds muscle", "lasts all day", "never ends"]'::jsonb,0,'Sugar spikes then drops.','original'),
('116.15.b.10.B',3,'Which drink best helps your body during exercise?','["energy drink", "water", "sugary juice", "soda"]'::jsonb,1,'Water hydrates without added sugar.','original'),
('116.15.b.11.A',3,'A pair of proper shoes for P.E. should be...','["too big", "slippery", "supportive and tied", "untied"]'::jsonb,2,'Good shoes prevent falls.','original'),
('116.15.b.11.A',3,'A mouthguard is used in contact sports to protect your...','["eyes", "ears", "toes", "teeth"]'::jsonb,3,'Mouthguards cover teeth.','original'),
('116.15.b.11.B',3,'Scooter safety includes wearing a...','["helmet and staying off busy streets", "swimsuit", "blindfold", "scarf"]'::jsonb,0,'Helmets and safe places keep riders safe.','original'),
('116.15.b.11.B',3,'Water safety rules say you should swim...','["during a storm", "only with a lifeguard or adult nearby", "in unknown water", "alone at night"]'::jsonb,1,'Never swim without supervision.','original'),
('116.15.b.11.B',3,'Sun safety includes...','["wearing a dark blanket", "no water", "using sunscreen and seeking shade", "staying in the sun all day"]'::jsonb,2,'Protect your skin.','original'),
('116.15.b.12.A',3,'When you choose to help a teammate, a consequence for others is that they...','["feel worse", "get angry", "lose the game", "feel supported"]'::jsonb,3,'Actions affect others.','original'),
('116.15.b.12.B',3,'A teammate with a different skill level should be treated with...','["respect", "pushing", "neglect", "jokes"]'::jsonb,0,'Respect applies to everyone.','original'),
('116.15.b.12.C',3,'Counting to ten before reacting is a self-management skill that helps you...','["get angrier", "calm down", "run away", "forget the rules"]'::jsonb,1,'It helps control impulses.','original'),
('116.15.b.13.A',3,'Cooperation in a team game means...','["ignoring teammates", "playing only for yourself", "working together toward a common goal", "arguing"]'::jsonb,2,'Teams succeed through cooperation.','original'),
('116.15.b.13.B',3,'If a classmate looks sad after losing, they may be feeling...','["excited", "proud", "silly", "disappointed"]'::jsonb,3,'Identify feelings by watching others.','original'),
('116.15.b.14',3,'Which shows perseverance during a hard fitness test?','["continuing even when tired", "blaming others", "refusing to try", "stopping early"]'::jsonb,0,'Perseverance is sticking with it.','original'),
('116.15.b.14',3,'Learning a new skill takes time. Perseverance helps you...','["quit", "keep practicing until you improve", "forget", "complain"]'::jsonb,1,'Persistence leads to success.','original'),
('116.15.b.15',3,'Constructive feedback should be...','["mean", "vague", "specific and kind", "rude"]'::jsonb,2,'It should help the person improve.','original'),
('116.15.b.15',3,'When you receive a correction from a coach, you should...','["argue", "laugh", "ignore", "listen carefully and try again"]'::jsonb,3,'Accepting feedback helps improvement.','original'),
('116.15.b.16.A',3,'Moderate activity is the kind that...','["makes you breathe a little harder but you can still talk", "is sleeping", "requires no effort", "makes you unable to speak"]'::jsonb,0,'Moderate effort is comfortable.','original'),
('116.15.b.16.A',3,'Vigorous activity is the kind that...','["is resting", "makes you breathe hard and unable to say more than a few words", "lets you chat easily", "is sleeping"]'::jsonb,1,'Vigorous effort is intense.','original'),
('116.15.b.16.B',3,'Selecting a physical activity you enjoy means you...','["only watch", "never exercise", "choose one that fits your interests", "pick the one you dislike"]'::jsonb,2,'Enjoyment keeps you active.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
